def makeIntersectionType(types: Iterable[Type]) = types.toList match {
  case Nil => ANY
  case t::Nil => t
  case ts@_ => SIntersectionType(makeInfo(ts), ts)
}

def makeUnionType(types: Iterable[Type]) = types.toList match {
  case Nil => BOTTOM
  case t::Nil => t
  case ts@_ => SUnionType(makeInfo(ts), ts)
}

